	@Test
	void nestedAndExceptionalExistsRestoreTheOuterLexicalFrame() throws Exception {
		SyntheticValueSource source = evaluationSource(true);
		NativeSlotLayout layout = scopedLayout();
		source.executionContext().initializeQueryBase(EmptyBindingSet.getInstance());
		Literal value = SimpleValueFactory.getInstance().createLiteral("outer");
		RowState row = scopedRow(source, layout, EmptyBindingSet.getInstance(), value);
		long originalInputMask = row.lexicalInputMask;
		int originalDepth = row.lexicalScopeDepth;
		PatternPlan pattern = new PatternPlan(Term.constant(SUBJECT), Term.constant(PREDICATE), Term.constant(OBJECT),
				Term.constant(LmdbNativeAggregateCompiler.NULL_CONTEXT_ID), ContextConstraint.UNRESTRICTED, false, 1D);
		ExistsFilter nested = new ExistsFilter(pattern);
		AtomicBoolean failOnce = new AtomicBoolean(true);
		List<Long> masksAfterNested = new ArrayList<>();
		List<Integer> depthsAfterNested = new ArrayList<>();
		SlotPlan nestedAndExceptional = new SlotPlan() {
			@Override
			public RowCursor open(RowState input) {
				if (failOnce.getAndSet(false)) {
					throw new IllegalStateException("simulated correlated evaluation failure");
				}
				if (!nested.accept(input)) {
					return new EmptyCursor();
				}
				masksAfterNested.add(input.lexicalInputMask);
				depthsAfterNested.add(input.lexicalScopeDepth);
				return new SingletonCursor();
			}

			@Override
			public long producedMask() {
				return 0L;
			}
		};
		ExistsFilter outer = new ExistsFilter(nestedAndExceptional);
		try {
			assertThatThrownBy(() -> outer.accept(row)).isInstanceOf(IllegalStateException.class);
			assertThat(row.lexicalInputMask).isEqualTo(originalInputMask);
			assertThat(row.lexicalScopeDepth).isEqualTo(originalDepth);
			assertThat(outer.accept(row)).isTrue();
			assertThat(masksAfterNested).containsExactly(row.boundMask());
			assertThat(depthsAfterNested).containsExactly(originalDepth + 1);
			assertThat(row.lexicalInputMask).isEqualTo(originalInputMask);
			assertThat(row.lexicalScopeDepth).isEqualTo(originalDepth);
		} finally {
			source.executionContext().close();
		}
	}

