	@Test
	void retainedConditionInputPreservesGraphAndNativeProofButDropsSibling() throws Exception {
		SyntheticValueSource source = evaluationSource(false);
		NativeSlotLayout proofLayout = singleSlotLayout("x");
		Literal languageTagged = SimpleValueFactory.getInstance().createLiteral("bonjour", "fr");
		long proofId = source.internComputedValue(languageTagged, proofLayout.positionMask("x"));
		Value graph = SimpleValueFactory.getInstance().createIRI("urn:active-graph");
		MutableBindingSet graphBase = new QueryBindingSet();
		graphBase = GraphFrameBindings.supply(graphBase, "graph", graph);
		RowBindingSetView provenBase = new RowBindingSetView(source, proofLayout, graphBase,
				new long[] { proofId }, true);
		BindingSet capturedEntry = NativeEntryBindings.snapshot(provenBase);
		NativeSlotLayout outerLayout = singleSlotLayout("sibling");
		RowState row = new RowState(source, outerLayout, capturedEntry);
		row.slots[0] = source.internComputedValue(SimpleValueFactory.getInstance().createLiteral("outer"),
				outerLayout.positionMask("sibling"));
		row.recomputeBoundMask();
		List<BindingSet> observedInputs = new ArrayList<>();
		List<Long> observedNativeIds = new ArrayList<>();
		SlotPlan inspectInput = new SlotPlan() {
			@Override
			public RowCursor open(RowState input) {
				observedInputs.add(input.view);
				observedNativeIds.add(((NativeEntryBindings) input.base).nativeId("x", input.source));
				return new SingletonCursor();
			}

			@Override
			public long producedMask() {
				return 0L;
			}
		};
		ExistsFilter exists = new ExistsFilter(inspectInput, Set.of("x", "graph"));
		try {
			assertThat(exists.accept(row)).isTrue();
			assertThat(observedInputs).hasSize(1);
			BindingSet retained = observedInputs.get(0);
			SoftAssertions softly = new SoftAssertions();
			softly.assertThat(retained.getValue("x")).isEqualTo(languageTagged);
			softly.assertThat(retained.hasBinding("sibling")).isFalse();
			softly.assertThat(GraphFrameBindings.isSupplied(retained, "graph")).isTrue();
			softly.assertThat(observedNativeIds).containsExactly(proofId);
			softly.assertAll();
		} finally {
			source.executionContext().close();
		}
	}

	@Test
	void nullContextMarkerIsUnboundForNativeBound() throws Exception {
		SyntheticValueSource source = evaluationSource(false);
		NativeSlotLayout layout = singleSlotLayout("x");
		QueryBindingSet inherited = new QueryBindingSet();
		inherited.setBinding("x", SimpleValueFactory.getInstance().createLiteral("inherited"));
		RowState marker = nullContextRow(source, layout, inherited);
		LmdbNativeCompiledBoolean bound = boundFilter(source, layout);
		try {
			assertThat(marker.view.getValue("x")).isNull();
			assertThat(bound.accept(marker))
					.as("the native null-context marker is not a SPARQL binding")
					.isFalse();

			RowState unknown = nullContextRow(source, layout, EmptyBindingSet.getInstance());
			unknown.slots[0] = NativeLmdbQuerySource.UNKNOWN_ID;
			unknown.recomputeBoundMask();
			assertThat(bound.accept(unknown)).isFalse();

			RowState integerZero = nullContextRow(source, layout, EmptyBindingSet.getInstance());
			integerZero.slots[0] = LmdbNativeValueCodec.packInline(
					LmdbNativeValueCodec.fromValue(SimpleValueFactory.getInstance().createLiteral(0)), false);
			integerZero.recomputeBoundMask();
			assertThat(bound.accept(integerZero))
					.as("the inline RDF literal zero has a nonzero native id and is bound")
					.isTrue();
		} finally {
			source.executionContext().close();
		}
	}

