	@Test
	void nullContextEntrySnapshotRetainsMarkerWithoutEmittingNullBinding() throws Exception {
		SyntheticValueSource source = evaluationSource(false);
		NativeSlotLayout layout = singleSlotLayout("x");
		QueryBindingSet inherited = new QueryBindingSet();
		inherited.setBinding("x", SimpleValueFactory.getInstance().createLiteral("inherited"));
		RowState marker = nullContextRow(source, layout, inherited);
		try {
			BindingSet entry = NativeEntryBindings.snapshot(marker.view);
			assertThat(entry.getBindingNames()).contains("x");
			assertThat(entry.hasBinding("x")).isTrue();
			assertThat(entry.getValue("x")).isNull();
			assertThat(entry.iterator()).toIterable().extracting(Binding::getName).doesNotContain("x");
			assertThat(((NativeEntryBindings) entry).nativeId("x", source))
					.isEqualTo(LmdbNativeAggregateCompiler.NULL_CONTEXT_ID);

			long[] seeded = new long[layout.slotNames().length];
			Arrays.fill(seeded, NativeLmdbQuerySource.UNKNOWN_ID);
			assertThat(NativeRowSeeder.seed(seeded, layout, entry, source)).isTrue();
			assertThat(seeded[layout.slot("x")]).isEqualTo(LmdbNativeAggregateCompiler.NULL_CONTEXT_ID);
			assertThat(marker.view.getValue("x")).isNull();
		} finally {
			source.executionContext().close();
		}
	}

