	@Test
	void changedLanguageTagSpellingDoesNotInheritAnEqualValueIdProof() throws Exception {
		SyntheticValueSource source = evaluationSource(false);
		NativeSlotLayout layout = scopedLayout();
		Literal lowercase = SimpleValueFactory.getInstance().createLiteral("bonjour", "fr");
		Literal uppercase = SimpleValueFactory.getInstance().createLiteral("bonjour", "FR");
		assertThat(lowercase).isEqualTo(uppercase);
		assertThat(lowercase.getLanguage()).isNotEqualTo(uppercase.getLanguage());
		RowState row = scopedRow(source, layout, EmptyBindingSet.getInstance(), lowercase);
		QueryBindingSet changed = new QueryBindingSet();
		changed.setBinding("x", uppercase);
		try {
			BindingSet entry = NativeEntryBindings.preserve(row.view, changed);
			assertThat(((NativeEntryBindings) entry).nativeId("x", source))
					.as("RDF equality does not preserve the exact native representative spelling")
					.isEqualTo(NativeLmdbQuerySource.UNKNOWN_ID);
			assertThat(entry.getValue("x").stringValue()).isEqualTo("bonjour");
			assertThat(((Literal) entry.getValue("x")).getLanguage()).contains("FR");
		} finally {
			source.executionContext().close();
		}
	}

